commands:
git fetch origin "+refs/heads/main:refs/remotes/origin/main" || { echo "fetch failed"; exit 1; }
BRANCH=$(.prflow/vendor/prflow/scripts/branch-for-issue.py 1540 --title-file .prflow/tmp/devflow-issue-1540-title.txt) || { echo "branch-for-issue failed"; exit 1; }
echo "BRANCH=$BRANCH"
git checkout -b "$BRANCH" "origin/main"
echo "checkout_exit=$?"
git branch --show-current
